'use strict';

/**
* LAPACK routine to compute an LQ factorization of a real M-by-N matrix `A = L * Q`, using Householder reflections (unblocked algorithm).
*
* @module @stdlib/lapack/base/dgelq2
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgelq2 = require( '@stdlib/lapack/base/dgelq2' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var work = new Float64Array( 3 );
*
* var out = dgelq2( 'column-major', 3, 4, A, 3, TAU, work );
* // ? => <Float64Array>[ ~-5.477, ~-12.78, ~-20.083, ~0.309, ~-3.266, ~-6.532, ~0.463, ~-0.327, ~0, ~0.618, ~-0.789, ~0.618 ]
* // TAU => <Float64Array>[ ~1.183, ~1.156, ~1.447 ]
* // work => <Float64Array>[ ~6.532, ~24.593, 0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dgelq2;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dgelq2 = main;
} else {
	dgelq2 = tmp;
}


// EXPORTS //

module.exports = dgelq2;

// exports: { "ndarray": "dgelq2.ndarray" }
